css:
.paper, .dialog, .popover, .composer, .turn, .message { border-radius: 0 !important; }
.button[data-variant=filled] { box-shadow: 3px 3px 0 0 var(--text); }
.actions, .screen-head .group { gap: 10px; padding: 0 3px 3px 0; }
.nav-item[data-active] { box-shadow: 3px 3px 0 0 var(--text); }
.h1, .h2, .h3 { text-transform: uppercase; letter-spacing: 0.04em; }
.backdrop { image-rendering: pixelated; mask-size: 360px; -webkit-mask-size: 360px; }
